import {SimpleListView} from '@github-ui/simple-list-view'
import {SimpleListItem} from '@github-ui/simple-list-view/SimpleListItem'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {Pagination} from '@primer/react'
import {useCallback, useState} from 'react'
import styles from './TeamsSettingsPage.module.css'

export interface TeamsSettingsPageProps {
  teams: Array<{
    id: string
    name: string
    url: string
    avatar_url: string
  }>
}

export function TeamsSettingsPage({teams}: TeamsSettingsPageProps) {
  const perPage = 20
  const pageCount = Math.ceil(teams.length / perPage)
  const [currentPage, setCurrentPage] = useState(1)
  const [teamsToDisplay, setTeamsToDisplay] = useState(teams.slice(0, perPage))

  const onPageChange = useCallback(
    (e: React.MouseEvent, page: number) => {
      setCurrentPage(page)
      setTeamsToDisplay(teams.slice((page - 1) * perPage, page * perPage))
      e.preventDefault()
    },
    [teams],
  )

  return (
    <>
      <SimpleListView>
        <SimpleListView.Items>
          {teamsToDisplay.map(team => (
            <SimpleListItem key={team.id}>
              <div className={styles.team}>
                <SimpleListItem.LeadingVisual>
                  <GitHubAvatar square src={team.avatar_url} />
                </SimpleListItem.LeadingVisual>
                <SimpleListItem.Title href={team.url}>{team.name}</SimpleListItem.Title>
              </div>
            </SimpleListItem>
          ))}
        </SimpleListView.Items>
      </SimpleListView>
      {pageCount > 1 && <Pagination pageCount={pageCount} currentPage={currentPage} onPageChange={onPageChange} />}
    </>
  )
}

try{ TeamsSettingsPage.displayName ||= 'TeamsSettingsPage' } catch {}